mapper.select:
SELECT resource_ref FROM audit_event a WHERE project_id=#{projectId} AND audit_id=#{auditId} AND subject_id=#{userId}
  AND action='upload.issued' AND result='SUCCESS' AND reason_code IS NULL AND request_id=#{requestId} AND trace_id=#{requestId}
  AND schema_version='1.0.0' AND schema_manifest_sha256=#{manifest} AND created_by=#{userId} AND classification=#{classification}
FOR UPDATE

mapper.update:
UPDATE operation_record o SET state='COMPLETED',http_status=200,response_ref=#{response},revision=2,updated_at=#{now}
WHERE subject_id=#{userId} AND operation_name='BX-04' AND idempotency_key=#{key} AND operation_id=#{operationId}
  AND request_sha256=#{requestHash} AND target_id=#{uploadId} AND state='PROCESSING' AND revision=1

UPDATE artifact_upload_grant g SET status='COMPLETED',artifact_id=#{artifactId},object_version=#{reference.objectVersion},
    object_identity_sha256=#{objectIdentitySha256},revision=revision+1,updated_at=#{now}
WHERE grant_id=#{grantId} AND subject_id=#{userId} AND purpose='DOCUMENT_BODY' AND revision=#{grantRevision}
  AND status IN ('ISSUED','UPLOADING') AND expires_at>#{now}
  AND object_key=#{reference.objectKey} AND sha256=#{reference.sha256} AND size_bytes=#{size}

