SELECT resource_ref FROM audit_event a WHERE project_id=#{projectId} AND audit_id=#{auditId} AND subject_id=#{userId}
  AND action='document.upload.completed' AND result='SUCCESS' AND reason_code IS NULL AND request_id=#{requestId}
  AND trace_id=#{requestId} AND schema_version='1.0.0' AND schema_manifest_sha256=#{manifest}
  AND created_by=#{userId} AND classification=#{classification} FOR UPDATE
